import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
const src = fs.readFileSync('src/lib/documentPriceSnapshot.ts','utf8');
const ctx = {exports:{}};
vm.runInNewContext(ts.transpileModule(src,{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,ctx);
const {snapshotDocumentLine,refreshDocumentLineCost,copyDocumentLineToNextStage}=ctx.exports;
const draft=snapshotDocumentLine({product_id:'a',unit_price:200,quantity:2,amount:0,cost:80});
assert.equal(draft.amount,400);
const refreshed=refreshDocumentLineCost(draft,120);
assert.equal(refreshed.unit_price,200);
assert.equal(refreshed.amount,400);
assert.equal(refreshed.cost,120);
assert.equal(draft.cost,80);
const converted=copyDocumentLineToNextStage(refreshed);
assert.equal(converted.unit_price,200);
assert.equal(converted.amount,400);
assert.throws(()=>refreshDocumentLineCost(draft,-1),/Invalid/);
console.log('Document price snapshot tests passed');
